import { chromium } from 'playwright';
const browser=await chromium.launch({headless:true});
const cases=[['desktop',1440,900],['laptop',1280,800],['mobile',390,844]];
let failed=false;const check=(ok,l,d='')=>{console.log(`${ok?'PASS':'FAIL'}: ${l}${d?` — ${d}`:''}`);if(!ok)failed=true};
for(const [name,width,height] of cases){const page=await browser.newPage({viewport:{width,height}});const ce=[],pe=[],bad=[];page.on('console',m=>{if(m.type()==='error')ce.push(m.text())});page.on('pageerror',e=>pe.push(String(e)));page.on('response',r=>{if(r.status()>=400)bad.push(`${r.status()} ${r.url()}`)});await page.goto('http://127.0.0.1:4173/docs/website/staging/#how-it-works',{waitUntil:'networkidle'});await page.locator('#how-it-works').scrollIntoViewIfNeeded();await page.waitForTimeout(200);const d=await page.evaluate(()=>{const s=document.querySelector('#how-it-works');const eyebrow=s?.querySelector('.eyebrow')?.textContent?.trim()||'';const badges=[...s.querySelectorAll('.how-step-badge')].map(x=>x.textContent.trim());const logo=s.querySelector('.flow-brand-logo img');const zones=s.querySelector('.flow-zones .flow-node-label')?.textContent?.trim()||'';const icons=s.querySelectorAll('.flow-mini-icon').length;return{eyebrow,badges,zones,icons,logoOk:!!logo&&logo.complete&&logo.naturalWidth>0,overflow:document.documentElement.scrollWidth-document.documentElement.clientWidth}});check(d.eyebrow==='ЯК ЦЕ ПРАЦЮЄ',`${name} eyebrow`,d.eyebrow);check(d.badges.length===4,`${name} step visuals`,d.badges.join(' | '));check(d.logoOk,`${name} horizontal BB610 WATER logo`);check(d.zones==='ЗОНИ ПОЛИВУ',`${name} irrigation zones label`,d.zones);check(d.icons===2,`${name} mini flow pictograms`,String(d.icons));check(d.overflow<=1,`${name} no horizontal overflow`,String(d.overflow));check(ce.length===0,`${name} console`,ce.join(' | '));check(pe.length===0,`${name} JS`,pe.join(' | '));check(bad.length===0,`${name} resources`,bad.join(' | '));await page.close()}
await browser.close();if(failed)process.exit(1);console.log('HOW IT WORKS SCREEN 4 REVIEW PASS');
